"use client"

import type { ReactNode } from "react"
import { useLayoutEffect, useRef } from "react"
import gsap from "gsap"
import { MotionConfig, motion } from "motion/react"

import HeroContent from "./hero-content"
import { HeroHalftoneImage } from "./hero-halftone-image"

const MEDIA_DELAY_S = 1.1

type HeroV4RootProps = {
  children?: ReactNode
  bgSrc: string
}

export function HeroV4Root({ children, bgSrc }: HeroV4RootProps) {
  const copyRootRef = useRef<HTMLDivElement>(null)

  useLayoutEffect(() => {
    const root = copyRootRef.current
    if (!root) return

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      gsap.set(
        root.querySelectorAll("[data-hero-v4-reveal], [data-hero-v4-word]"),
        {
          clearProps: "all",
        }
      )
      return
    }

    const ctx = gsap.context(() => {
      const reveals = gsap.utils.toArray<HTMLElement>("[data-hero-v4-reveal]")
      const words = gsap.utils.toArray<HTMLElement>("[data-hero-v4-word]")

      const tl = gsap.timeline()

      tl.fromTo(
        words,
        { opacity: 0, filter: "blur(9px)", x: 20 },
        {
          opacity: 1,
          filter: "blur(0px)",
          x: 0,
          duration: 0.54,
          stagger: { each: 0.08, from: "start" },
          ease: "power3.out",
          clearProps: "transform,filter",
        }
      )

      tl.fromTo(
        reveals[0],
        { opacity: 0, y: 16 },
        {
          opacity: 1,
          y: 0,
          duration: 0.55,
          ease: "power2.out",
          clearProps: "transform",
        },
        "-=0.22"
      )

      tl.fromTo(
        reveals[1],
        { opacity: 0, y: 10, scale: 0.96 },
        {
          opacity: 1,
          y: 0,
          scale: 1,
          duration: 0.48,
          ease: "power2.out",
          clearProps: "transform",
        },
        "-=0.28"
      )
    }, root)

    return () => ctx.revert()
  }, [])

  return (
    <MotionConfig reducedMotion="user">
      <div ref={copyRootRef} className="mx-auto max-w-6xl px-4">
        <div className="flex flex-col items-center gap-6 text-center">
          {children}
          <HeroContent />
        </div>
      </div>

      <div className="mx-auto max-w-4xl px-4 pt-4">
        <motion.div
          className="hero-v4__media relative aspect-video w-full overflow-hidden rounded-xl"
          initial={{ opacity: 0, y: 28, scale: 0.98 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          transition={{
            delay: MEDIA_DELAY_S,
            duration: 0.72,
            ease: [0.22, 1, 0.36, 1],
          }}
        >
          <HeroHalftoneImage src={bgSrc} />
        </motion.div>
      </div>
    </MotionConfig>
  )
}

import { IBM_Plex_Serif } from "next/font/google"

import CtaButtons from "./cta-buttons"

const ibmPlexSerif = IBM_Plex_Serif({
  subsets: ["latin"],
  weight: ["400", "500", "600"],
})

const TITLE_WORDS = ["Turn", "AI", "from", "noise", "into", "results."]

export default function HeroContent() {
  return (
    <div className="flex flex-col items-center gap-6 text-center">
      <h1
        className={`${ibmPlexSerif.className} text-3xl tracking-tighter sm:text-4xl lg:text-5xl lg:leading-[1.15]`}
      >
        {TITLE_WORDS.map((word, i) => (
          <span key={i} data-hero-v4-word className="inline-block">
            {i < TITLE_WORDS.length - 1 ? word + "\u00A0" : word}
          </span>
        ))}
      </h1>

      <div data-hero-v4-reveal>
        <p className="max-w-xl text-base leading-7 tracking-tight text-muted-foreground sm:text-lg sm:leading-8">
          We find where AI can save you time and money, then build the systems
          that make it happen.
        </p>
      </div>

      <div data-hero-v4-reveal>
        <CtaButtons />
      </div>
    </div>
  )
}

"use client"

import { HalftoneDots } from "@paper-design/shaders-react"

type HeroHalftoneImageProps = {
  src: string
}

export function HeroHalftoneImage({ src }: HeroHalftoneImageProps) {
  return (
    <HalftoneDots
      aria-hidden={true}
      className="absolute inset-0 h-full w-full"
      colorBack="#f2f1e8"
      colorFront="#2b2b2b"
      contrast={0.5}
      fit="cover"
      grainMixer={0.4}
      grainOverlay={0.2}
      grainSize={0.5}
      grid="hex"
      image={src}
      inverted={false}
      originalColors={false}
      radius={1.5}
      size={0.2}
      type="gooey"
    />
  )
}

@media (prefers-reduced-motion: no-preference) {
  [data-hero-v4-reveal],
  [data-hero-v4-word] {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-hero-v4-reveal],
  [data-hero-v4-word] {
    opacity: 1;
    transform: none;
    filter: none;
  }
}
